SELECT stat_time, SUM(new_chat_cnt) AS new_chat_cnt, SUM(chat_total) AS chat_total, SUM(chat_has_msg) AS chat_has_msg, SUM(new_member_cnt) AS new_member_cnt, SUM(member_total) AS member_total, SUM(member_has_msg) AS member_has_msg, SUM(msg_total) AS msg_total, SUM(migrate_trainee_chat_cnt) AS migrate_trainee_chat_cnt FROM crm_wecom_groupchat_daily WHERE stat_time BETWEEN #{startTime} AND #{endTime}
AND owner_userid IN
#{uid}
GROUP BY stat_time ORDER BY stat_time
